"use client"

import animation from "react-useanimations/lib/tool"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Tool" from https://useanimations.com (MIT): https://useanimations.com/icons/tool
export function AnimatedTool(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
